"use client";

import * as React from "react";
import {
  Area,
  AreaChart as RechartsAreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { cn } from "@/lib/utils";
import {
  AreaFillDefs,
  type AreaFillVariant,
  AnimatedDashedStroke,
  ChartActiveDot,
  type ChartDatum,
  ChartFrame,
  ChartGlowFilter,
  chartGrid,
  ChartLegend,
  ChartLoadingBars,
  ChartPlotSurface,
  type ChartSeries,
  ChartTooltipContent,
  chartXAxis,
  chartYAxis,
  type ChartDotRenderProps,
  compactFormatValue,
  RevealMask,
  resolveSeries,
  type StrokeVariant,
  areaFillUrl,
  strokeDasharray,
  useChartId,
  useChartMotion,
  useIntroStartedAt,
} from "@/components/moneytrees/charts/chart-kit";

export type { AreaFillVariant };

export type AreaCurve = "monotone" | "bump" | "step" | "linear";
export type AreaStackType = "none" | "stacked" | "expanded";

export interface SpectrumAreaChartProps {
  className?: string;
  data: ChartDatum[];
  xKey: string;
  series: ChartSeries[];
  variant?: AreaFillVariant;
  curveType?: AreaCurve;
  stackType?: AreaStackType;
  strokeVariant?: StrokeVariant;
  glowing?: boolean;
  isLoading?: boolean;
  showLegend?: boolean;
  showGrid?: boolean;
  height?: number;
  formatX?: (value: string | number) => string;
  formatValue?: (value: number) => string;
}

export function AreaChart({
  className,
  data,
  xKey,
  series,
  variant = "gradient",
  curveType = "monotone",
  stackType = "none",
  strokeVariant = "solid",
  glowing = false,
  isLoading = false,
  showLegend = true,
  showGrid = true,
  height,
  formatX,
  formatValue,
}: SpectrumAreaChartProps) {
  const id = useChartId("area");
  const { reduce } = useChartMotion();
  const introStartedAt = useIntroStartedAt();
  const lines = resolveSeries(series);
  const stacked = stackType !== "none";
  const glowId = `${id}-glow`;
  const maskId = `${id}-reveal`;
  const maskStyle = reduce ? undefined : { mask: `url(#${maskId})` };

  return (
    <ChartFrame className={cn("flex flex-col", className)} height={height}>
      {showLegend && lines.length > 1 ? <ChartLegend items={lines} /> : null}
      {isLoading ? (
        <ChartLoadingBars />
      ) : (
        <ChartPlotSurface>
          <ResponsiveContainer width="100%" height="100%">
            <RechartsAreaChart
              data={data}
              stackOffset={stackType === "expanded" ? "expand" : undefined}
              margin={{ top: 8, right: 8, left: 0, bottom: 0 }}
            >
              <defs>
                {lines.map((s) => (
                  <AreaFillDefs
                    key={s.key}
                    id={`${id}-${s.key}`}
                    color={s.color}
                    variant={variant}
                  />
                ))}
                {glowing ? <ChartGlowFilter id={glowId} /> : null}
                <RevealMask id={maskId} introStartedAt={introStartedAt} reduce={reduce} />
              </defs>
              {showGrid ? <CartesianGrid {...chartGrid} /> : null}
              <XAxis {...chartXAxis} dataKey={xKey} tickFormatter={formatX} />
              <YAxis
                {...chartYAxis}
                hide={stackType === "expanded"}
                tickFormatter={formatValue ?? compactFormatValue}
              />
              <Tooltip
                cursor={{ stroke: "currentColor", strokeOpacity: 0.22, strokeDasharray: "4 4" }}
                content={<ChartTooltipContent formatValue={formatValue} formatLabel={formatX} />}
              />
              {lines.map((s, i) => (
                <Area
                  key={s.key}
                  type={curveType}
                  dataKey={s.key}
                  name={s.label}
                  stroke={s.color}
                  strokeWidth={2}
                  strokeDasharray={strokeDasharray(strokeVariant)}
                  fill={areaFillUrl(`${id}-${s.key}`, variant, s.color)}
                  fillOpacity={variant === "solid" ? 0.28 : 1}
                  stackId={stacked ? "stack" : undefined}
                  isAnimationActive={false}
                  activeDot={(props: ChartDotRenderProps) => (
                    <ChartActiveDot cx={props.cx} cy={props.cy} color={s.color} />
                  )}
                  filter={glowing && i === 0 ? `url(#${glowId})` : undefined}
                  style={maskStyle}
                >
                  {strokeVariant === "animated-dashed" ? <AnimatedDashedStroke /> : null}
                </Area>
              ))}
            </RechartsAreaChart>
          </ResponsiveContainer>
        </ChartPlotSurface>
      )}
    </ChartFrame>
  );
}
